window.ScripturaLexicons.BDAG_PART_0261 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-01\" data-source=\"BDAG\" data-search=\"ὅτε partícula temporal quando; enquanto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅτε</td><td>partícula temporal</td><td>quando; enquanto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-02\" data-source=\"BDAG\" data-search=\"ὁτέ advérbio temporal ora; numa ocasião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁτέ</td><td>advérbio temporal</td><td>ora; numa ocasião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-03\" data-source=\"BDAG\" data-search=\"ὅτι conjunção que; porque; pois; de modo que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅτι</td><td>conjunção</td><td>que; porque; pois; de modo que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-04\" data-source=\"BDAG\" data-search=\"ὅτου forma pronominal genitivo de ὅστις BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅτου</td><td>forma pronominal</td><td>genitivo de ὅστις</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-05\" data-source=\"BDAG\" data-search=\"οὗ advérbio de lugar onde; para onde; em que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὗ</td><td>advérbio de lugar</td><td>onde; para onde; em que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-06\" data-source=\"BDAG\" data-search=\"οὐ advérbio negativo não; negação objetiva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐ</td><td>advérbio negativo</td><td>não; negação objetiva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-07\" data-source=\"BDAG\" data-search=\"οὐά interjeição ah!; admiração; desdém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐά</td><td>interjeição</td><td>ah!; admiração; desdém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-08\" data-source=\"BDAG\" data-search=\"οὐαί interjeição/substantivo ai!; lamento; desgraça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐαί</td><td>interjeição/substantivo</td><td>ai!; lamento; desgraça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-09\" data-source=\"BDAG\" data-search=\"Οὐαλέριος, ου, ὁ nome próprio masculino Valério BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Οὐαλέριος, ου, ὁ</td><td>nome próprio masculino</td><td>Valério</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-10\" data-source=\"BDAG\" data-search=\"οὐδαμῶς advérbio negativo de modo nenhum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐδαμῶς</td><td>advérbio negativo</td><td>de modo nenhum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-11\" data-source=\"BDAG\" data-search=\"οὐδέ conjunção negativa nem; tampouco; nem sequer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐδέ</td><td>conjunção negativa</td><td>nem; tampouco; nem sequer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-12\" data-source=\"BDAG\" data-search=\"οὐδείς, οὐδεμία, οὐδέν adjetivo/pronome nenhum; ninguém; nada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐδείς, οὐδεμία, οὐδέν</td><td>adjetivo/pronome</td><td>nenhum; ninguém; nada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-13\" data-source=\"BDAG\" data-search=\"οὐδέποτε advérbio temporal negativo nunca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐδέποτε</td><td>advérbio temporal negativo</td><td>nunca</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-14\" data-source=\"BDAG\" data-search=\"οὐδέπω advérbio temporal negativo ainda não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐδέπω</td><td>advérbio temporal negativo</td><td>ainda não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-15\" data-source=\"BDAG\" data-search=\"οὐθείς forma pronominal variante de οὐδείς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐθείς</td><td>forma pronominal</td><td>variante de οὐδείς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-16\" data-source=\"BDAG\" data-search=\"οὐκέτι advérbio não mais; nunca mais; portanto não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐκέτι</td><td>advérbio</td><td>não mais; nunca mais; portanto não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-17\" data-source=\"BDAG\" data-search=\"οὐκοῦν advérbio portanto; então BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐκοῦν</td><td>advérbio</td><td>portanto; então</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-18\" data-source=\"BDAG\" data-search=\"Οὐλαμμαούς nome próprio variante de Emaús BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Οὐλαμμαούς</td><td>nome próprio</td><td>variante de Emaús</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-19\" data-source=\"BDAG\" data-search=\"οὖλος, η, ον adjetivo crespo; encaracolado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὖλος, η, ον</td><td>adjetivo</td><td>crespo; encaracolado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0261-20\" data-source=\"BDAG\" data-search=\"οὐ μεν οὖν locução adverbial absolutamente não; de modo nenhum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οὐ μεν οὖν</td><td>locução adverbial</td><td>absolutamente não; de modo nenhum</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0261-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅτε</h1><div class=\"entry-meta\"><span>partícula temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅτε</span> (Hom. e posteriores), partícula temporal. ① Marcador de um ponto no tempo que coincide com outro ponto temporal, quando. ⓐ Como conjunção, com indicativo. <span class=\"greek\">α</span>. Presente (ApcSed 16:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:1</a> (aqui, presente histórico). <span class=\"greek\">β</span>. Imperfeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:6</a>; 22:20. <span class=\"greek\">γ</span>. Predominantemente com aoristo (B-D-F § 382, 1; Rob. 971), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:25</a>; 13:48; 21:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:32</a>; 4:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a>, 42; 15:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:19</a>; 2:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:13</a>; 8:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:15</a>; 2:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:10</a>. <span class=\"greek\">ὅτε</span> <span class=\"greek\">ἐπιστεύσαμεν</span>, quando cremos pela primeira vez, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a> e outros; GJs 12:3; 25:1.—Com <span class=\"greek\">τότε</span> a seguir (ApcMos 19; Jos., C. Ap. 1, 127; com <span class=\"greek\">τότε</span> antes, D. 141, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:26</a>; 21:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:16</a>. Mt emprega não raramente a fórmula de transição <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ὅτε</span> em passagens narrativas, «e aconteceu que, quando …» (4 Km 14:5), 7:28; 11:1; 13:53; 19:1; 26:1. <span class=\"greek\">ἀφότε</span> (cf. 2 Esdr 5:12 <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὅτε</span>), desde então, Hs 8, 6. <span class=\"greek\">μέχρι</span> <span class=\"greek\">ὅτε</span>, até quando, GJs 10:2. <span class=\"greek\">δ</span>. Perfeito: <span class=\"greek\">ὅτε</span> <span class=\"greek\">γέγονα</span> <span class=\"greek\">ἀνήρ</span>, quando me tornei homem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:11b</a>. ⓑ Em substituição ao pronome relativo após substantivo que denota tempo. <span class=\"greek\">α</span>. Presente do indicativo: <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">νὺξ</span> <span class=\"greek\">ὅτε</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">ἐργάζεσθαι</span>, vem a noite em que ninguém pode trabalhar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:4</a>. <span class=\"greek\">β</span>. Futuro (Just., D. 14, 8; 40, 2): <span class=\"greek\">ἐλεύσονται</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ὅτε</span> <span class=\"greek\">ἐπιθυμήσετε</span>, virão dias em que desejareis, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:22</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">ὅτε</span> <span class=\"greek\">κρινεῖ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, no dia em que Deus julgará, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:16</a>. <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">ὥρα</span>, <span class=\"greek\">ὅτε</span> … <span class=\"greek\">προσκυνήσετε</span>, vem a hora em que … adorareis, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:21</a>. Cf. versículo 23; 5:25; 16:25. <span class=\"greek\">καιρὸς</span> <span class=\"greek\">ὅτε</span>, tempo em que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:3</a>. <span class=\"greek\">γ</span>. Com subjuntivo aoristo (<span class=\"greek\">ὅτε</span> com subjuntivo, desde Hom., na poesia épica [SibOr 8, 50] e lírica; mas também Vett. Val. 106, 36 <span class=\"greek\">ὅτε</span> <span class=\"greek\">ἄρξηται</span>; TestAbr A 9 p. 87, 5 [Stone p. 22] <span class=\"greek\">ὅτε</span> <span class=\"greek\">ἴδω</span> <span class=\"greek\">ταῦτα</span>, <span class=\"greek\">τότε</span> …; 11 p. 89, 24): <span class=\"greek\">ἕως</span> <span class=\"greek\">ἥξει</span> <span class=\"greek\">ὅτε</span> <span class=\"greek\">εἴπητε</span>, até que chegue o tempo em que digais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:35</a> (texto incerto; ver B-D-F § 382, 2; Rob. 971f). ② Marcador de período coextensivo a outro período, enquanto, durante o tempo em que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:20</a>; 7:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:2</a>; 13:11a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:17</a>; Hv 3, 6, 7 e outros.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁτέ</h1><div class=\"entry-meta\"><span>advérbio temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁτέ</span>, advérbio (Hom. e outros; inscrições), marcador de um ponto temporal coincidente com outro, antecipando um correlativo, em certo momento, numa ocasião. Esse uso encontra-se normalmente na estrutura <span class=\"greek\">ὁτὲ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὁτὲ</span> <span class=\"greek\">δὲ</span> …, «ora … ora …» (Aristot., Pol. 2, 2, 16; Parthenius 27, 2; Dio Chrys. 50 [67], 5; Polyaenus 5, 22, 4; SIG 679, 83f), mas <span class=\"greek\">ὁτὲ</span> <span class=\"greek\">μὲν</span> …, «num dado momento», 2:4, tem como correlativo <span class=\"greek\">λέγει</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πάλιν</span>, «mas diz novamente» (sobre variações no grego mais antigo, ver L-S-J-M s.v. <span class=\"greek\">ὅτε</span> C; quanto ao texto, ver Hdb ad loc.).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅτι</h1><div class=\"entry-meta\"><span>conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅτι</span> (Hom. e posteriores), conjunção (B-D-F § 396f; 408; 416; 470, 1 e outros; Rob. 1032–36 e outros [ver índice]; HPernot, Études sur la langue des Évang. 1927, 41ff), originalmente neutro de <span class=\"greek\">ὅστις</span>. ① Marcador do conteúdo de narração ou discurso, direto ou indireto, que. Usado depois de verbos que denotam percepção mental ou sensorial, a transmissão dessa percepção ou um ato da mente, para indicar o conteúdo do que se diz etc. ⓐ Após verbos de dizer, indicar e semelhantes: <span class=\"greek\">ἀπαγγέλλω</span>, <span class=\"greek\">ἀποκρίνομαι</span>, <span class=\"greek\">δείκνυμι</span>, <span class=\"greek\">δῆλόν</span> (<span class=\"greek\">ἐστιν</span>), <span class=\"greek\">διδάσκω</span>, <span class=\"greek\">εἶπον</span>, <span class=\"greek\">ἐμφανίζω</span>, <span class=\"greek\">λέγω</span>, <span class=\"greek\">μαρτυρέω</span>, <span class=\"greek\">ὁμολογέω</span>, <span class=\"greek\">φημί</span> etc.; ver os verbetes respectivos. Também após verbos de jurar, afirmar e fórmulas correspondentes: <span class=\"greek\">μαρτύρομαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:3</a>. <span class=\"greek\">μάρτυρα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐπικαλοῦμαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:23</a>. <span class=\"greek\">ὀμνύω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:6</a>. Cf. expressões semelhantes <span class=\"greek\">πιστὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:18</a>. <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:20</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:10</a>. Cf. também <span class=\"greek\">φάσις</span> … <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:31</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">γραφαὶ</span> <span class=\"greek\">ὅτι</span>, as Escrituras (que afirmam) que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:54</a>.—Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:12</a>–14, ver BNoack, NTS 6, ’60, 236–41. ⓑ Após verbos de percepção sensorial: <span class=\"greek\">ἀκούω</span>, <span class=\"greek\">θεάομαι</span>, <span class=\"greek\">θεωρέω</span> (ver esse verbete, 1); ver os verbetes respectivos. ⓒ Após verbos de percepção mental: <span class=\"greek\">ἀγνοέω</span>, <span class=\"greek\">ἀναγινώσκω</span>, <span class=\"greek\">βλέπω</span> («perceber»), <span class=\"greek\">γινώσκω</span>, <span class=\"greek\">γνωστόν</span> <span class=\"greek\">ἐστιν</span>, <span class=\"greek\">ἐπιγινώσκω</span>, <span class=\"greek\">ἐπίσταμαι</span>, <span class=\"greek\">θεωρέω</span> (ver esse verbete, 2a), <span class=\"greek\">καταλαμβάνω</span>, <span class=\"greek\">μιμνῄσκομαι</span>, <span class=\"greek\">μνημονεύω</span>, <span class=\"greek\">νοέω</span>, <span class=\"greek\">οἶδα</span>, <span class=\"greek\">ὁράω</span> (ver esse verbete, A4a), <span class=\"greek\">συνίημι</span>, <span class=\"greek\">ὑπομιμνῄσκω</span>; ver os verbetes respectivos. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:11</a>, <span class=\"greek\">ὅτι</span> aparece mais adiante na frase para permitir que a porção enfática da oração subordinada venha para o primeiro plano. ⓓ Após verbos de pensar, julgar, crer e esperar: <span class=\"greek\">δοκέω</span> (ver verbete 1d), <span class=\"greek\">ἐλπίζω</span> (ver 2), <span class=\"greek\">κρίνω</span>, <span class=\"greek\">λογίζομαι</span>, <span class=\"greek\">νομίζω</span> (ver 2), <span class=\"greek\">οἶμαι</span>, <span class=\"greek\">πέπεισμαι</span>, <span class=\"greek\">πέποιθα</span>, <span class=\"greek\">πιστεύω</span> (ver 1a <span class=\"greek\">β</span>), <span class=\"greek\">ὑπολαμβάνω</span>; ver esses verbetes. <span class=\"greek\">εἶχον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωάννην</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">ἦν</span>, consideravam João um profeta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:32</a> (ver B-D-F § 330; 397, 2; Rob. 1029; 1034). ⓔ Após verbos que denotam emoção e sua expressão: <span class=\"greek\">ἀγανακτέω</span>, <span class=\"greek\">ἐξομολογέομαι</span>, <span class=\"greek\">ἐπαινέω</span>, <span class=\"greek\">εὐχαριστέω</span>, <span class=\"greek\">θαυμάζω</span>, <span class=\"greek\">μέλει</span> <span class=\"greek\">μοι</span>, <span class=\"greek\">συγχαίρω</span>, <span class=\"greek\">χαίρω</span>, <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">τινί</span>; ver esses verbetes. ⓕ Muito frequentemente o sujeito da oração com <span class=\"greek\">ὅτι</span> é atraído para a oração principal e se torna objeto desta: <span class=\"greek\">ἐπεγίνωσκον</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ὅτι</span> (= <span class=\"greek\">ὅτι</span> <span class=\"greek\">αὐτοὶ</span>) <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἦσαν</span>, reconheciam que eles estavam com Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:13</a>. <span class=\"greek\">οἴδατε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">Στεφανᾶ</span> <span class=\"greek\">ὅτι</span> (= <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">Σ</span>.) <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἀπαρχή</span>, sabeis que a casa de Estéfanas é primícias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:15</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.54\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:54</a>; 9:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:20</a> (Ps 93:11); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:8</a>. Às vezes, o sujeito é retomado por pronome demonstrativo na oração com <span class=\"greek\">ὅτι</span>: <span class=\"greek\">ἐκήρυσσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, proclamava Jesus, que este é o Filho de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:20</a>.—Passiva: <span class=\"greek\">εἰ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">κηρύσσεται</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἐγήγερται</span> (= <span class=\"greek\">εἰ</span> <span class=\"greek\">κηρύσσεται</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκ</span>. <span class=\"greek\">ἐγ</span>.), se se prega Cristo como ressuscitado dentre os mortos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:12</a>. ② Marcador de orações explicativas, que. ⓐ Em lugar do infinitivo epexegético (acusativo com infinitivo), após demonstrativo precedente (B-D-F § 394; cf. Rob. 1034): <span class=\"greek\">αὕτη</span> <span class=\"greek\">δέ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κρίσις</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐλήλυθεν</span>, o julgamento consiste nisto: que a luz veio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:19</a>. <span class=\"greek\">ἔστιν</span> <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγγελία</span> …, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐστιν</span>, esta é a mensagem …: que Deus é luz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:5</a>. Cf. 3:16; 4:9, 10. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> …, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">δέδωκεν</span> <span class=\"greek\">ἡμῖν</span>, nisto …, que nos deu do seu Espírito, versículo 13; 5:11. <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span> … <span class=\"greek\">ὅτι</span>, acerca disto …, que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:19</a>. Em <span class=\"greek\">ἔχω</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">ὅτι</span> …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:4</a>, <span class=\"greek\">ὅτι</span> é epexegético a um <span class=\"greek\">τοῦτο</span> não expresso. Cf. versículo 6. ⓑ Do mesmo tipo é o uso em elipses: <span class=\"greek\">τί</span> <span class=\"greek\">ὅτι</span>;, «o que (é) que?», «por quê?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a>, 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:16</a>, variante de leitura (JosAs 16:5).—<span class=\"greek\">οὐχ</span> <span class=\"greek\">ὅτι</span> (= <span class=\"greek\">οὐ</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ὅτι</span>), não que, não como se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:46</a>; 7:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:24</a>; 3:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12</a>; 4:11; 2Th 3:9 (assim <span class=\"greek\">μὴ</span> <span class=\"greek\">ὅτι</span>, PLond I 42, 43 p. 30 [II a.C.]). <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὅτι</span>, pois não se trata de que, IMg 3:2.—<span class=\"greek\">οὐχ</span> <span class=\"greek\">οἷον</span> <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:6</a> (ver <span class=\"greek\">οἷος</span>).—<span class=\"greek\">ὅτι</span> isolado equivale a <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐκεῖνο</span> <span class=\"greek\">ὅτι</span>, a respeito do fato de que, levando em consideração que (Gen 40:15; Ruth 2:13): <span class=\"greek\">ποταπός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὅτι</span>;, que espécie de pessoa é esta, considerando que …?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:27</a> (mas provavelmente nessa e em passagens semelhantes predomina a força causal de <span class=\"greek\">ὅτι</span> [ver 4 abaixo]). <span class=\"greek\">τίς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὅτι</span>;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:36</a>. Cf. 16:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:18</a>; 8:22; 9:17; 11:47; 16:9–11.—<span class=\"greek\">ὅτι</span> = <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ὅτι</span>, nisto que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:8</a>. <span class=\"greek\">ὅτι</span> = <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">ὅτι</span>, acerca disto, que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:17</a>.—Sobre <span class=\"greek\">ὅτι</span> = «por quê?» (cf. Jos., Ant. 12, 213), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:11</a>, 28, ver <span class=\"greek\">ὅστις</span> 4b. ③ Marcador que introduz discurso direto. Nesse caso, não deve ser traduzido como palavra, mas representado por aspas (<span class=\"greek\">ὅτι</span> recitativum.—B-D-F § 397, 5; 470, 1; EKieckers, IndogF 35, 1915, 21ff; Rob. 1027f. Já em Pla. [Apol. 23, 34 d.—Kühner-G. II, 366f]; Epict. 1, 9, 16; Arrian, Alex. An. 2, 12, 4; 2, 26, 4; 4, 8, 9; Philostrat., Vi. Apoll. 1, 38 p. 40; POxy 744, 11 [1 a.C.]; 119, 10; 1064, 5; LXX; TestAbr A 8 p. 85, 10 [Stone p. 18]; TestJob 6:7; 35:1; 36:3; ParJer 1:6; 2:7; ApcEsdr; AscIs 3:9; Jos. Ant. 11, 5; 18, 326, Vi. 55): <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">λέγετε</span> <span class=\"greek\">ὅτι</span> «<span class=\"greek\">βλασφημεῖς</span>» <span class=\"greek\">ὅτι</span> <span class=\"greek\">εἶπον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:36</a>. <span class=\"greek\">ὁμολογήσω</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὅτι</span> «<span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">ἔγνων</span> <span class=\"greek\">ὑμᾶς</span>», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:23</a>. Assim, após diversos verbos de dizer em discurso direto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.72\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:72</a>–75; 27:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:37</a>; 2:16; 5:28; 12:29; 13:6 (JSundwall, Om bruket av <span class=\"greek\">ὅτι</span> recit. i Mk: Eranos 31, ’33, 73–81; MZerwick, Untersuchgen z. Mk-Stil ’37, 39–48); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:25</a>, 61 (PWinter, HTR 48, ’55, 213–16); 4:41a; 5:26; 15:27a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:20</a>, 32; 4:17; 6:42; 16:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:23</a>; 15:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:8</a> (B-D-F § 470, 1; Rob. 1033; AFridrichsen, ZNW 34, ’35, 306–8); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:20</a> e outros. As citações das Escrituras também são introduzidas assim (Appian, Bell. Civ. 62 §260, um dito de César em discurso direto introduzido por <span class=\"greek\">ὅτι</span>): <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">ἔγραψεν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὅτι</span> «<span class=\"greek\">ἐάν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">κτλ</span>.», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:19</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>; 21:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:18</a>.—Quanto a <span class=\"greek\">ὅτι</span> seguido de acusativo e infinitivo em discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:43</a>, ver 5a abaixo. ④ Marcador de causalidade. ⓐ Subordinando, porque, visto que: <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἑώρακάς</span> <span class=\"greek\">με</span>, <span class=\"greek\">πεπίστευκας</span>, porque me viste, creste, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:29</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a> (Jer 38:15); 5:3ff; 13:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:34</a>; 5:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:41b</a>; 6:20ff; 8:30; 10:13; 11:42ff; 13:2b; 15:27b; talvez 18:9 (TManson, The Sayings of Jesus ’54, 309); 19:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:30</a>, 50a; 2:25; 3:18; 5:27; 9:16, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:15f</a>. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:12</a>–14, ver BNoack, NTS 6, ’60, 236–41 (que se opõe ao sentido causal).—Empregado com pronomes demonstrativos e interrogativos: <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span> … <span class=\"greek\">ὅτι</span>, por esta razão …, a saber, que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:47</a>; 10:17; 12:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:1</a> e outros. <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span>; <span class=\"greek\">ὅτι</span> …, por quê? porque …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:11</a>. <span class=\"greek\">χάριν</span> <span class=\"greek\">τίνος</span>; <span class=\"greek\">ὅτι</span> …, por qual razão? porque …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:12</a>. Seguido de <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span>, porque …, por essa razão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:19</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὅτι</span> … <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ὅτι</span>, não porque …, mas porque, 6:26; 12:6. ⓑ Frequentemente a subordinação é tão frouxa que a tradução «pois» se recomenda (B-D-F § 456, 1; Rob. 962f). Naturalmente, não é possível traçar com certeza a linha divisória entre os dois grupos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:13</a>; 11:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:47</a> (sobre essa passagem e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:14</a>, ver Schwyzer II 646, com referência à Il. 16, 34f: «deduzi isso do fato de que»); 9:12; 13:31; 16:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:16f</a>; 9:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:25</a>; 4:9; 10:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:6</a>; 7:8, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:14</a>.—MBlack, An Aramaic Approach 3, ’67, 70ff. ⑤ Empregos especiais. ⓐ <span class=\"greek\">ὅτι</span> com acusativo e infinitivo depois de <span class=\"greek\">θεωρεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:10</a> (sobre a mistura de construções, cf. POxy 237 V, 8 <span class=\"greek\">δηλῶν</span> <span class=\"greek\">ὅτι</span> … <span class=\"greek\">δεῖσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρᾶγμα</span>; EpArist 125; escólio a Clem. de Alex., Protr. p. 296, 11f Stäh.—B-D-F § 397, 6; Rob. 1036; Rdm. 2 195; MArnim, De Philonis Byzantii dicendi genere, dissertação Greifs-wald 1912, 88 [mas ver Rdm. 2 196, 1]). Menos irregular é <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅτι</span> com verbo finito como segundo membro dependente de <span class=\"greek\">παρακαλεῖν</span> após o infinitivo <span class=\"greek\">ἐμμένειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:22</a>.—Ver também c abaixo e HCadbury, JBL 48, 1929, 412–25. ⓑ <span class=\"greek\">ὡς</span> <span class=\"greek\">ὅτι</span> ocorre três vezes nas cartas paulinas e no vernáculo posterior significa simplesmente «que» (exemplos em Mlt. 212; B-D-F § 396; Rob. 1033). Mas deve-se admitir o sentido subjetivo de <span class=\"greek\">ὡς</span> no NT, pois a Vulgata traduz <span class=\"greek\">ὡς</span> <span class=\"greek\">ὅτι</span> duas vezes por «quasi» (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>) e na terceira vez (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:19</a>) por «quoniam quidem»: <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐπιστολῆς</span> …, <span class=\"greek\">ὡς</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐνέστηκεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, por uma carta … (cujo conteúdo afirmava) que (na opinião de seu autor) o dia do Senhor já chegou, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>. Paulo diz ironicamente: <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀτιμίαν</span> <span class=\"greek\">λέγω</span>, <span class=\"greek\">ὡς</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἠσθενήκαμεν</span>, devo confessar, para minha vergonha, que nos comportamos como fracos (como devo reconhecer ao comparar minha conduta com o tratamento violento que recebestes de outros [versículo 20]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:21</a> (quanto ao pensamento, cf. Demosth. 18, 320: «confesso. Sou fraco, mas tanto mais leal que tu [Ésquines] aos meus concidadãos»). Semelhantemente, 5:19; somos nova criação em Cristo (versículo 17). Isso não modifica o fato de que tudo se origina em Deus, que nos reconciliou consigo por Cristo (versículo 18): <span class=\"greek\">ὡς</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">καταλλάσσων</span> <span class=\"greek\">ἑαυτῷ</span>, isto é (segundo a convicção do próprio Paulo), que era Deus quem reconciliava consigo o mundo em Cristo. ⓒ <span class=\"greek\">ὅτι</span> consecutivo, de modo que (Pel.-Leg. p. 20 <span class=\"greek\">τί</span> <span class=\"greek\">διδοῖς</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀμνοῖς</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">ἔχουσιν</span>;, «que dás às tuas ovelhas, para que tenham vida eterna?»; Acta Christophori p. 68, 18 Usener <span class=\"greek\">τοιοῦτοι</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">ὑμῶν</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">ἐκινήθησαν</span>. Gen 20:9; Judg 14:3; 1 Km 20:1; 3 Km 18:9): <span class=\"greek\">ποῦ</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">μέλλει</span> <span class=\"greek\">πορεύεσθαι</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὑρήσομεν</span> <span class=\"greek\">αὐτόν</span>;, para onde irá este homem, de modo que não o encontraremos?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:35</a>. <span class=\"greek\">τί</span> <span class=\"greek\">γέγονεν</span> <span class=\"greek\">ὅτι</span> … ;, que aconteceu, para que (= para produzir o resultado de que) …?, 14:22 (assim Rob. 1001; diferentemente Rdm. 2 196 e B-D-F § 480, 6). Provavelmente também pertence aqui <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">εἰσηνέγκαμεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἐξενεγκεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">δυνάμεθα</span>, nada trouxemos ao mundo, de modo que (consequentemente) nada podemos retirar dele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:7</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἄνθρωπος</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">μιμνῄσκῃ</span> <span class=\"greek\">αὐτοῦ</span>;, que é o homem, para que te lembres dele?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a> (Ps 8:5).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅτου</h1><div class=\"entry-meta\"><span>forma pronominal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅτου</span>, genitivo singular masculino e neutro de <span class=\"greek\">ὅστις</span> (ver esse verbete, 6).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὗ</h1><div class=\"entry-meta\"><span>advérbio de lugar</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὗ</span>, originalmente genitivo de <span class=\"greek\">ὅς</span>, tornou-se advérbio de lugar (Aeschyl. e outros; inscrições, papiros, LXX, En, EpArist, Philo, Joseph.). ① Marcador de posição no espaço, onde. ⓐ De localização sem referência ao deslocamento de uma entidade. <span class=\"greek\">α</span>. Sem referência a substantivo precedente: <span class=\"greek\">οὕ</span> …, <span class=\"greek\">ἐκεῖ</span>, onde …, aí, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:26</a> (Hos 2:1). Sem <span class=\"greek\">ἐκεῖ</span>, IPhld 8:1. <span class=\"greek\">β</span>. Principalmente depois de substantivo que denota lugar, em lugar do pronome relativo, em que, no qual, sobre o qual (Jos., Ant. 8, 349): <span class=\"greek\">εἰς</span> <span class=\"greek\">Ναζαρά</span>, <span class=\"greek\">οὗ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τεθραμμένος</span>, a Nazaré, onde fora criado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:16</a>. Cf. versículo 17; 23:53; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:13</a>; 2:2; 7:29; 12:12; 16:13 e outros.—O lugar em que: <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span>, acima do lugar onde estava o menino, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a> (cf. X., An. 1, 7, 6 <span class=\"greek\">μέχρι</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">καῦμα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνανται</span> <span class=\"greek\">οἰκεῖν</span>). ⓑ De localização como destino, onde, para onde (GDI 1758, 8; 1766, 7 [ambos em Delfos]; SIG 374, 25; Bar 2:4, 13; GrBar 10:5 [<span class=\"greek\">οὗπερ</span>]; EpArist 269): <span class=\"greek\">εἰς</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">πόλιν</span> … <span class=\"greek\">οὗ</span> <span class=\"greek\">ἤμελλεν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἔρχεσθαι</span>, a toda cidade aonde ele próprio estava para ir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:1</a>. <span class=\"greek\">ἐπορεύθησαν</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐτάξατο</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span>, foram … ao monte ao qual Jesus lhes ordenara ir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:16</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κώμην</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐπορεύοντο</span>, à aldeia para onde caminhavam, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:28</a>.—<span class=\"greek\">οὗ</span> <span class=\"greek\">ἐάν</span>, com subjuntivo presente referente ao futuro (IG IV 2 /1, 68, 71; 73 [302 a.C.]; PSI 902, 4 [I d.C.]): <span class=\"greek\">ἄπειμι</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">βούλησθε</span>, irei para onde quiserdes, 1 Cl 54:2. <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">πορεύωμαι</span>, para onde quer que eu vá, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:6</a>. ② Marcador de situação ou conjunto de circunstâncias, algo como «numa situação em que», extensão figurada de 1 (Jos., Ant. 2, 272): <span class=\"greek\">οὗ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">παράβασις</span>, onde não existe lei, tampouco existe transgressão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:15</a>. Cf. 5:20. <span class=\"greek\">οὗ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐλευθερία</span>, onde está o Espírito do Senhor, há liberdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:17</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐ</h1><div class=\"entry-meta\"><span>advérbio negativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐ</span> (Hom. e posteriores; ver Schwyzer II 591–94), advérbio de negação objetiva (em oposição ao subjetivo <span class=\"greek\">μή</span>), negando a realidade de um fato alegado; no NT é usado com o indicativo (<span class=\"greek\">μή</span> serve de negação dos demais modos, inclusive infinitivo e particípio, com certas exceções discutidas adiante. Ver B-D-F § 426; Rob. 1168f; Mlt-Turner 281f). Diante de vogais com espírito brando, toma a forma <span class=\"greek\">οὐκ</span>; diante das que têm espírito áspero, <span class=\"greek\">οὐχ</span>; nos manuscritos essa regra é frequentemente desconsiderada (W-S. §5, 10bc; B-D-F § 14; Rob. 224). Sobre seu emprego, ver B-D-F § 426 –33; Rdm. 2 p. 210ff; Rob. 1155–66. ① Resposta negativa a pergunta ou afirmação, na forma acentuada <span class=\"greek\">οὔ</span>, não, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:29</a> (Schwyzer II 596f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:21</a>; 7:12; 21:5. <span class=\"greek\">ἤτω</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὒ</span> <span class=\"greek\">οὔ</span>, seja o vosso «não», «não», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>. Duplicado para ênfase (ver <span class=\"greek\">ναί</span> e.—<span class=\"greek\">οὒ</span> <span class=\"greek\">οὔ</span>, Nicetas Eugen. 5, 76 H. Do mesmo modo <span class=\"greek\">μὴ</span> <span class=\"greek\">μή</span> = «não, não!» [Herodas 3, 71; Meleager, I a.C., em Anth. Pal. 12, 80, 3; Psellus p. 268, 15 <span class=\"greek\">μὴ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μάγιστρε</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:17ff</a>. Sobre <span class=\"greek\">οὐ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span>, ver <span class=\"greek\">οὐμενοῦν</span>. ② Marcador de proposições negativas, não. ⓐ Usado para negar palavras ou orações isoladas (Ar. 13, 7 <span class=\"greek\">μῦθοί</span> <span class=\"greek\">εἰσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἄλλο</span> <span class=\"greek\">τι</span>; Just., A II, 2, 2 <span class=\"greek\">οὐ</span> <span class=\"greek\">σωφρόνως</span>; Tat. 5, 1 <span class=\"greek\">οὐ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀποκοπήν</span>;—como no grego anterior, Hom. e outros; ver Kühner-G. II, 182; Schwyzer II 593f). <span class=\"greek\">α</span>. <span class=\"greek\">οὐ</span> <span class=\"greek\">πᾶς</span>, nem todo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:21</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">πάντες</span>, nem todos, 19:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:6</a>; 10:16. <span class=\"greek\">πάντες</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κοιμηθησόμεθα</span>, nem todos adormeceremos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.51\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:51</a> (ver JBurn, ET, 1926, 236f; POppenheim, TQ 112, ’31, 92–135; AVaccari, Biblica 13, ’32, 73–76; B-D-F § 433, 2; Rob. 753). Também com transposição, <span class=\"greek\">διατί</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μετενόησαν</span>;, por que nem todos se arrependeram?, Hs 8, 6, 2. <span class=\"greek\">οὐ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">σάρξ</span>, nem toda carne, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:39</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">πάντως</span>, de modo nenhum, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:10</a>.—<span class=\"greek\">καλέσω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">λαόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">λαόν</span> <span class=\"greek\">μου</span>, aos que não eram meu povo chamarei «meu povo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:25a</a> (Hos 2:25b); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:10</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔθνος</span>, povo que não é nação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:19</a> (Dt 32:21). <span class=\"greek\">β</span>. Frequentemente em litotes (cf. Lysias 13, 62 <span class=\"greek\">εἰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">ἦσαν</span>; Tat. 3, 2): <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλοί</span>, <span class=\"greek\">πολλαί</span>, não muitos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:5</a> (<span class=\"greek\">οὐ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολλὰς</span> <span class=\"greek\">ἡμέρας</span> = <span class=\"greek\">μετ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλ</span>. <span class=\"greek\">ἡμ</span>.; cf. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὄντων</span> = <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὄντων</span>, 2 Macc 7:28). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀλίγος</span>, <span class=\"greek\">ὀλίγη</span>, <span class=\"greek\">ὀλίγοι</span>, <span class=\"greek\">ὀλίγαι</span>, não poucos (muitos), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:4</a>, 12; 19:23f; 27:20. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἄσημος</span>, não insignificante, 21:39. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἁγνῶς</span>, não puramente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:17</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μετρίως</span>, não moderadamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:12</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέτρου</span>, sem medida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:34</a>. <span class=\"greek\">μετ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">πολύ</span>, pouco tempo depois, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:14</a>. Ver também <span class=\"greek\">δ</span> adiante. <span class=\"greek\">γ</span>. Negação em contraste: <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνθρώποις</span>, ao Senhor e não aos homens, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:23</a>. <span class=\"greek\">τρέχω</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀδήλως</span>, corro como quem não corre sem rumo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:26</a>. <span class=\"greek\">δ</span>. Como perífrase de conceitos expressos por verbos: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀγνοεῖν</span>, saber muito bem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:11</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐᾶν</span>, impedir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:7</a> (cf. Il. 2, 132); 19:30. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχειν</span>, carecer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:25</a> (sobre essas duas passagens, ver Schwyzer II 593, com referência a Kühner-G. II 189–92; contraste com o uso de <span class=\"greek\">μή</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:18</a>). <span class=\"greek\">οὐ</span> <span class=\"greek\">θέλειν</span>, recusar-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:10</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">πταίειν</span>, não tropeçar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:2</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὑπακούειν</span>, desobedecer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:14</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">φιλεῖν</span>, não estimar, tratar de maneira inamistosa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:22</a>. ⓑ Usado às vezes com o particípio. Dos casos de a acima decorrem as situações em que isso acontece, contrariando a regra enunciada no começo do artigo. Além disso, é provável que em exemplos isolados ainda atue a influência literária antiga (para o grego anterior, ver Kühner-G. II 198–203; <span class=\"greek\">μή</span> sugere contingência).—B-D-F § 430; Mlt. 231f (com exemplos dos papiros; cf. Just., A I, 33, 4 <span class=\"greek\">οὐ</span> <span class=\"greek\">συνουσιασθεῖσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρθένον</span>; 67, 5 <span class=\"greek\">τοῖς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">παροῦσι</span> e outros); Rdm. 2 212; Mlt-Turner 284f. <span class=\"greek\">α</span>. Para negar um conceito isolado: <span class=\"greek\">πράγματα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">βλεπόμενα</span>, coisas não vistas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:1</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τυχών</span>, extraordinário, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:11</a>; 28:2 (cf. Com. Att. Fgm. III 442 nº 178 <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τυχοῦσι</span>). <span class=\"greek\">θλιβόμενοι</span> <span class=\"greek\">ἀλλ</span>’, <span class=\"greek\">οὐ</span> <span class=\"greek\">στενοχωρούμενοι</span>, atribulados, mas não angustiados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:8</a>; cf. versículo 9. <span class=\"greek\">β</span>. Com ênfase forte ou contraste: <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐνδεδυμένον</span> <span class=\"greek\">ἔνδυμα</span> <span class=\"greek\">γάμου</span>, homem não vestido com traje nupcial (destacando a inadequação de sua vestimenta), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:11</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">προσδεξάμενοι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπολύτρωσιν</span>, não aceitando o livramento (realçando o grande heroísmo desse ato), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:35</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">βλέπων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:42</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἰδόντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:8</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τέκνου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:5</a>.—Contraste: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:19</a>. <span class=\"greek\">τότε</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰδότες</span> <span class=\"greek\">θεὸν</span> … <span class=\"greek\">νῦν</span> <span class=\"greek\">δέ</span>, outrora não conhecendo a Deus … agora, porém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:8</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span>, introduzindo contraste, também é empregado com particípio: <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">πεποιθότες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:3</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κρατῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:19</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">μισθωτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">ποιμήν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:12</a>. <span class=\"greek\">γ</span>. Nas citações da LXX no NT, observa-se a tendência dos tradutores do AT de traduzir regularmente <span class=\"hebrew\" dir=\"rtl\">לֹא</span>, com particípio, por <span class=\"greek\">οὐ</span>: <span class=\"greek\">ἡ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τίκτουσα</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὠδίνουσα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:27</a> (Is 54:1). <span class=\"greek\">τὴν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἠγαπημένην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:25b</a> (Hos 2:25a). <span class=\"greek\">οἱ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἠλεημένοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:10</a> (Hos 1:6). <span class=\"greek\">δ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνήκοντα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:4</a>, variante de leitura, é presumivelmente mistura de <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀνήκοντα</span> e da leitura do próprio texto <span class=\"greek\">ἃ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνῆκεν</span> (já em P 46). ⓒ Em orações principais. <span class=\"greek\">α</span>. Em afirmações simples com indicativo: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγίνωσκεν</span> <span class=\"greek\">αὐτήν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:25</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνασθε</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">δουλεύειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαμωνᾷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἤφιεν</span> <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δαιμόνια</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:34</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τέκνον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:7</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐστιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:7</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐπαισχύνομαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:16</a>, e muito frequentemente. <span class=\"greek\">οὐ</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἠκούσαμέν</span> <span class=\"greek\">ποτε</span>, AcPlCor 1:14. <span class=\"greek\">β</span>. Para negar o futuro proibitivo (hebraico <span class=\"hebrew\" dir=\"rtl\">לֹא</span> com imperfeito.—Synes., Ep. 67 p. 211b <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀγνοήσεις</span>): <span class=\"greek\">οὐ</span> <span class=\"greek\">φονεύσεις</span>, não matarás, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:21</a>; cf. versículo 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:7</a>; 13:9 (todos mandamentos do Decálogo: Ex 20:13–17; Dt 5:17–21). Também <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπιορκήσεις</span>, não jurarás falsamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:33</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐκπειράσεις</span> <span class=\"greek\">κύριον</span>, não tentarás o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:12</a> (Dt 6:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:5</a> (Ex 22:27); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:9</a> (Dt 25:4).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:5</a>. ⓓ Em orações subordinadas. <span class=\"greek\">α</span>. Em relativas com indicativo (no NT, <span class=\"greek\">μή</span> ocorre nessas orações apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:3</a> [mas ver B-D-F § 428, 4 e Rob. 1158]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:29</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>, variante de leitura): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:38</a>; 12:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:25</a> (ver 2a <span class=\"greek\">δ</span> acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.64\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:64</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:21</a> (Is 52:15); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:10</a> (Dt 27:26) e outros. <span class=\"greek\">β</span>. Em orações declarativas com <span class=\"greek\">ὅτι</span> e, igualmente, em temporais e causais com indicativo: <span class=\"greek\">ὅτι</span> <span class=\"greek\">οὐ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:1</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀρνούμενος</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριοτός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:22</a> (sobre a negação aqui, ver <span class=\"greek\">ἀρνέομαι</span> 2).—<span class=\"greek\">ἐπει</span> <span class=\"greek\">οὐ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:34</a>. <span class=\"greek\">ὅτε</span> <span class=\"greek\">οὐ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:3</a>.—<span class=\"greek\">εἰ</span> <span class=\"greek\">οὐ</span> com indicativo: <span class=\"greek\">εἰ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δώσει</span> <span class=\"greek\">αὐτῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:8</a>; cf. <span class=\"greek\">ὅστις</span> (<span class=\"greek\">ὸ̔ς</span>) <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:12</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:25</a> = <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:18</a> (Schwyzer II 593). <span class=\"greek\">εἰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀλλοτρίῳ</span> <span class=\"greek\">πιστοὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγένεσθε</span>, 16:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:25</a>; 10:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:9b</a>; 11:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:25</a>.—Uma única vez, de fato, em condição contrafactual: <span class=\"greek\">καλὸν</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγεννήθη</span>, melhor lhe fora se não tivesse nascido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:24</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:21</a> = 1 Cl 46:8 (B-D-F § 428, 2; Rob. 1160; Mlt-Turner 284). ⓔ Em combinação com outras negativas, reforçando a negação (Mel. Chor. Adesp., Fgm. nº 11 Diehl 2 [’42] <span class=\"greek\">οὐ</span> <span class=\"greek\">μήποτε</span> <span class=\"greek\">τὰν</span> <span class=\"greek\">ἀρετὰν</span> <span class=\"greek\">ἀλλάξομαι</span> <span class=\"greek\">ἀντ</span>’ <span class=\"greek\">ἀδίκου</span> <span class=\"greek\">κέρδεος</span>, «jamais trocarei a virtude por lucro injusto»; GrBar 13:3 <span class=\"greek\">οὐκ</span> … <span class=\"greek\">οὐδέν</span>; Just., D. 26, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:2</a>; 23:53 (<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὔπω</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:63</a>; 11:49; 12:19; 15:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:9</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μηκέτι</span> (ver <span class=\"greek\">μηκέτι</span> f <span class=\"greek\">α</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:19</a>, variante de leitura. Sobre o emprego em perguntas, ver 3 abaixo. <span class=\"greek\">α</span>. Sobre a combinação de <span class=\"greek\">οὐ</span> e <span class=\"greek\">μή</span>, ver <span class=\"greek\">μή</span> 4. <span class=\"greek\">β</span>. A combinação de <span class=\"greek\">οὐδέ</span> com <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span>, formando <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span> em vez de <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">μή</span>, é desenvolvimento tardio (barbarismo?; B-D-F § 431, 3; Rob. 1175; Mlt-Turner 286.—Oração ao deus Socnopaeus: Mitt-Wilck I/2, 122, 2ff <span class=\"greek\">εἰ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δίδοταί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">συμβιῶσαι</span> <span class=\"greek\">Ταπεθεῦτι</span> <span class=\"greek\">Μαρρείους</span> <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">ἄλλου</span> <span class=\"greek\">γυνή</span> [Rdm. 2 211f]; LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἀνῶ</span> <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἐγκαταλίπω</span>, não te deixarei nem te abandonarei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:5</a> (Dt 31:6 A, 8 A <span class=\"greek\">οὐδ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span>; 1 Ch 28:20 A).—<span class=\"greek\">οὐδὲν</span> … <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀδικήσει</span> em lugar de <span class=\"greek\">οὐδὲν</span> … <span class=\"greek\">μὴ</span> …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:19</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λήψῃ</span>, Hm 9:5. ⓕ Com uma de duas orações coordenadas ou contrastadas. <span class=\"greek\">α</span>. <span class=\"greek\">οὐ</span> … <span class=\"greek\">ἀλλά</span>, ver <span class=\"greek\">ἀλλά</span> 1ab.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:4</a>, <span class=\"greek\">οὐ</span> com o particípio deve provavelmente ser explicado sob esse tópico (ver 3 acima). <span class=\"greek\">β</span>. <span class=\"greek\">οὐ</span> …, … <span class=\"greek\">δέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:9</a>, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:13</a>, 15. <span class=\"greek\">γ</span>. …, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐ</span>, retomando algo afirmado com ressalva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:5</a>, 23. <span class=\"greek\">δ</span>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μόνον</span>, <span class=\"greek\">ἀλλὰ</span> (<span class=\"greek\">καί</span>), ver <span class=\"greek\">μόνος</span> 2c. <span class=\"greek\">ε</span>. <span class=\"greek\">οὐ</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span>, ver <span class=\"greek\">εἰ</span> 6i. ③ Marcador de expectativa de resposta afirmativa, não é assim? ⓐ Em pergunta direta (Hom. e outros). <span class=\"greek\">α</span>. «Não …?» (B-D-F § 427, 2; Rob. 917): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀκούεις</span>, <span class=\"greek\">πόσα</span> <span class=\"greek\">σου</span> <span class=\"greek\">καταμαρτυροῦσιν</span>;, ouves, não é?, quanto testemunham contra ti?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:13</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">διαφέρετε</span> <span class=\"greek\">αὐτῶν</span>;, não valeis vós muito mais que eles?, 6:26. Cf. versículo 30. <span class=\"greek\">ὁ</span> <span class=\"greek\">διδάσκαλος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τελεῖ</span> <span class=\"greek\">δίδραχμα</span>;, vosso mestre paga o imposto de duas dracmas, não paga?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:24</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:3</a>; 7:18; 12:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:35</a>; 6:70; 7:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:21</a>, e frequentemente. <span class=\"greek\">οὐ</span> <span class=\"greek\">μέλει</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἀπολλύμεθα</span>;, não te importa que pereçamos?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:38</a>. Em sentido relacionado: <span class=\"greek\">β</span>. Desfazendo a força da negação (cf. Hdt. e outros; Schwyzer II 598), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:15</a> (B-D-F § 431, 1; Rob. 1164).—Nas perguntas, quando o próprio verbo já está negado (por <span class=\"greek\">οὐ</span>), a negação pode ser invalidada pela partícula interrogativa <span class=\"greek\">μή</span> (ver <span class=\"greek\">μή</span> 3a), que espera a resposta «não», preparando, assim, uma resposta afirmativa (Aesop, Fab. 374 P.=404aH. <span class=\"greek\">μὴ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστι</span> <span class=\"greek\">χλόη</span>;, certamente há erva, não há?): <span class=\"greek\">μὴ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἤκουσαν</span>;, porventura não ouviram?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:18</a>; cf. versículo 19. <span class=\"greek\">μὴ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">ἐξουσίαν</span>;, não temos o direito?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:4</a>; cf. versículo 5. <span class=\"greek\">μὴ</span> <span class=\"greek\">οἰκίας</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχετε</span>;, não tendes casas?, 11:22. ⓑ Em pergunta formulada impacientemente na segunda pessoa do futuro do indicativo e funcionando como imperativo: <span class=\"greek\">οὐ</span> <span class=\"greek\">παύσῃ</span>; = <span class=\"greek\">παῦσαι</span>!, não vais parar? = para!, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:10</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐά</h1><div class=\"entry-meta\"><span>interjeição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐά</span> (também <span class=\"greek\">οὐᾶ</span>; texto recebido <span class=\"greek\">οὐαί</span>; cf. Proleg. Syllog. p. 101), interjeição de admiração (Epict. 3, 23, 24 <span class=\"greek\">εἰπέ</span> <span class=\"greek\">μοι</span> «<span class=\"greek\">οὐά</span>» <span class=\"greek\">καὶ</span> «<span class=\"greek\">θαυμαστῶς</span>»; 32; 3, 22, 34; Cass. Dio 63, 20.—Kühner-Bl. II 252; Schwyzer II 601), ah! Como expressão de admiração desdenhosa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:29</a>. Expressão de júbilo, conforme a leitura dos marcosianos de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:26</a> (Iren. 1, 20, 2 [Harv. I 180, 3]).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐαί</h1><div class=\"entry-meta\"><span>interjeição/substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐαί</span> (LXX; cf. <span class=\"hebrew\" dir=\"rtl\">הוֹי</span>, <span class=\"hebrew\" dir=\"rtl\">אוֹי</span> e latim vae; En; TestAbr B 9, 16 [Stone p. 74]; TestJob 22:2; 53:2; ParJer 9:8; ApcEsdr. Mas também Epict. 3, 19, 1; ibidem e 3, 22, 32 <span class=\"greek\">οὐαί</span> <span class=\"greek\">μοι</span>; Vi. Aesopi W 37 <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀτυχίᾳ</span>; POxy 413, 184f <span class=\"greek\">οὐαί</span> <span class=\"greek\">σοι</span>, <span class=\"greek\">ταλαίπωρε</span> … <span class=\"greek\">οὐαί</span> <span class=\"greek\">σοι</span>· <span class=\"greek\">οὐαί</span> <span class=\"greek\">μοι</span>. Schwyzer II 143; B-D-F § 4, 2a; ALowe, The Origin of <span class=\"greek\">οὐαί</span>: Hermathena 105, ’67, 34–39. Empréstimo na literatura rabínica). ① Interjeição que exprime dor ou desagrado, ai!, lamentação. ⓐ Com dativo de pessoa ou coisa relativamente à qual se exprime dor (ver acima; frequentemente LXX; cf. Jos., Bell. 6, 306 <span class=\"greek\">αἰαὶ</span> <span class=\"greek\">Ἱεροσολύμοις</span>): <span class=\"greek\">οὐαί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">Χοραζίν</span>, <span class=\"greek\">οὐαί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">Βηθσαϊδά</span>(<span class=\"greek\">ν</span>), ai de ti, Corazim; ai de ti, Betsaida!, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:13</a> (cf. Jer 13:27).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:7b</a>; 23:13–16, 23, 25, 27, 29 (sobre o tom severo nessas passagens, ver ASaldarini, Understanding Matthew’s Vitriol, BRev 13/2, ’97, 32–39, 45); 24:19; 26:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:17</a>; 14:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:23</a>; 22:22; 1 Cl 46:8 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:24</a>); Hv 4, 2, 6; D 1:5; GPt 7:25; GJs 20:1 (códices).—Duplicado por ênfase (Am 5:16.—Procop. Soph., Ep. 36 e 62 <span class=\"greek\">ἰοὺ</span> <span class=\"greek\">ἰού</span> = «ai, ai!»): três vezes com dativo seguinte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:13</a>, variante de leitura.—<span class=\"greek\">οὐαὶ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">ἔρχεται</span> (= <span class=\"greek\">τούτῳ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐρχ</span>.), ai daquele por meio de quem vem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:1</a>; cf. 2 Cl 13:2; ITr 8:2.—Com <span class=\"greek\">ὅτι</span> a seguir indicando a razão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:24f</a>; 11:42–44, 47, 52; também versículo 46, com a diferença de que aqui <span class=\"greek\">οὐαί</span> vem depois: <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">νομικοῖς</span> <span class=\"greek\">οὐαί</span>, <span class=\"greek\">ὅτι</span>. Cf. Jd 11; 2 Cl 17:5; B 6:2, 7 (Is 3:9).—Com preposição <span class=\"greek\">ἀπό</span> a seguir, também indicando razão: <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σκανδάλων</span>, ai do mundo por causa dos escândalos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:7a</a>; com <span class=\"greek\">ὅταν</span> a seguir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:26</a>.—A transição ao grupo seguinte é assinalada por <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">ὑμῖν</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐμπεπλησμένοι</span>, versículo 25a. ⓑ Com nominativo e artigo funcionando como vocativo: <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">γελῶντες</span> <span class=\"greek\">νῦν</span>, ai dos que agora riem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:25b</a> (cf. Am 5:18; Hab 2:6, 12; Zeph 2:5). <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span>, ai, ai da grande cidade!, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:10</a>, 16, 19 (para gregos, tal interjeição sugeria nêmesis; cf. Hes., Op. 200f). <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">συνετοί</span>, ai dos sábios, 4:11 (Is 5:21). Também sem artigo: <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">τυφλοὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁρῶντες</span>, ai dos cegos que não veem, Ox 840, 31f (Unknown Sayings 36–49). ⓒ Com acusativo de pessoa (B-D-F § 190, 2; Rob. 1193; cf. latim vae me), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:12</a>. <span class=\"greek\">οὐαί</span> repetido três vezes, 8:13 (a razão do «ai» é introduzida por <span class=\"greek\">ἐκ</span>). ② Estado de extrema dificuldade ou aflição, desgraça, ai, substantivo indeclinável (Ezk 2:10; 7:26; Kephal. I 105, 3; B-D-F § 58; Rob. 302): <span class=\"greek\">οὐαί</span> <span class=\"greek\">μοί</span> <span class=\"greek\">ἐστιν</span>, ai de mim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:16</a> (cf. Hos 9:12). Como feminino <span class=\"greek\">ἡ</span> <span class=\"greek\">οὐαί</span>, ai, calamidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:12a</a>; 11:14ab. Plural: <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">δύο</span> <span class=\"greek\">οὐαί</span>, ainda vêm dois ais, 9:12b (falta concordância numérica [B-D-F § 136, 5], como em Hes., Theog. 321 <span class=\"greek\">τῆς</span> <span class=\"greek\">δ</span>’ [da Quimera] <span class=\"greek\">ἦν</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">κεφαλαί</span>. O escólio de Hes. explica essa característica como dórica; crítica de B-D-F, ver PKatz, TLZ 82, ’57, 112).—DELG. M-M. EDNT. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Οὐαλέριος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Οὐαλέριος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, Valério, frequentemente encontrado como nome de uma gens romana (Diod S 11, 41, 1; 11, 60, 1; 13, 76, 1; 16, 46, 1); Valério com o cognome Bito, 1 Cl 65:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐδαμῶς</h1><div class=\"entry-meta\"><span>advérbio negativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐδαμῶς</span>, advérbio de <span class=\"greek\">οὐδαμός</span>, «nem um» (Aeschyl., Hdt. e posteriores; também SIG 679, 80; PTebt 24, 53 [117 a.C.]; 27, 41 [113 a.C.]; 58, 4 [111 a.C.]), marcador de negação enfática, de modo nenhum, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a>; Papias (2:2).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐδέ</h1><div class=\"entry-meta\"><span>conjunção negativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐδέ</span>, conjunção negativa, combinação de <span class=\"greek\">οὐ</span> e <span class=\"greek\">δέ</span> (Hom. e posteriores). ① E não, nem: liga sentenças ou orações negativas a outras de mesma natureza. <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐδέ</span> no início de uma frase, 10:4. Depois de <span class=\"greek\">οὐ</span>: <span class=\"greek\">κλέπται</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">διορύσσουσιν</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">κλέπτουσιν</span>, ladrões não escavam nem roubam, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:20</a>; cf. versículo 28; 5:15; 7:18; 10:24; 25:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:43f</a>; 12:24, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:27</a> (Ps 15:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:1</a>; 3:28ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:22</a> (cf. Is 53:9); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:23</a>; AcPlCor 1:4. <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐδέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:13</a>, 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:3</a>; AcPlCor 1:11, 15. Depois de <span class=\"greek\">οὔπω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:17</a>. Depois de <span class=\"greek\">οὐδείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a>; 11:27; 22:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:3</a> (<span class=\"greek\">οὐδεὶς</span> … <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐδέ</span>). <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> … <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐδέ</span>, 9:4.—<span class=\"greek\">οὐδὲ</span> <span class=\"greek\">γάρ</span>, pois … não, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:5</a>; 8:42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:12</a>, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:7</a>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">γὰρ</span> … <span class=\"greek\">οὐδένα</span>, pois … não … ninguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:22</a>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πέσῃ</span> (cf. Is 49:10 A), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:16</a>. ② Também não, tampouco, nem: <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀφῆτε</span> …, <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀφήσει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">παραπτώματα</span> <span class=\"greek\">ὑμῶν</span>, se não perdoardes …, vosso Pai tampouco perdoará vossas transgressões, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:15</a>. Cf. 21:27; 25:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:15</a>; 11:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:13</a>, 16; GJs 16:3. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐγὼ</span> … <span class=\"greek\">παρέλαβον</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">οὔτε</span> (variante <span class=\"greek\">οὐδέ</span>) …, pois eu tampouco o recebi … nem …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:12</a>. <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐδέ</span>, e tampouco, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:15</a>. ③ Nem sequer, nem mesmo, latim ne … quidem (B-D-F § 445, 2; Rob. 1185; Libanius, Or. 11 p. 439, 14 F. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">συγγνώμη</span> = nem mesmo indulgência; Just., D. 12, 2 <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">νῦν</span>, nem mesmo agora; Tat. 30, 1; Ath. 13, 1 <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ὄναρ</span>): <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">Σολομὼν</span> <span class=\"greek\">περιεβάλετο</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">τούτων</span>, nem mesmo Salomão se vestiu como um deles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:29</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:9</a>; 12:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:1</a>. <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ἄν</span> (X., Cyr. 8, 8, 3; Herodian 2, 8, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:4</a>. <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">οὕτως</span>, nem mesmo então, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:21</a>. <span class=\"greek\">οὐδεὶς</span> … <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐδὲ</span> …, ninguém … nem mesmo … e nem mesmo …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:32</a>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γραφὴν</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἀνέγνωτε</span>;, nunca sequer lestes essa passagem das Escrituras?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:10</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:3</a>. Igualmente em outras perguntas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:40</a> (cf. Lucian, Asin. 24 <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δαιμόνια</span> <span class=\"greek\">δέδοικα</span>;); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:14</a>.—<span class=\"greek\">καὶ</span> <span class=\"greek\">οὐδέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:31</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἁλύσει</span> (<span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἐδύνατο</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">δῆσαι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:3</a>.—<span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐδέ</span> (TestJob 47:10; ApcEsdr 4:4; Just., D. 3, 6), mas nem mesmo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:2</a>; 4:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:3</a>.—<span class=\"greek\">οὐδὲ</span> <span class=\"greek\">εἷς</span>, nem sequer um (X., Mem. 3, 5, 21; Dionys. Hal. 1, 73; Nicol. Dam.: 90 Fgm. 103m, 2 Jac. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">κλέπτει</span>; 2 Km 13:30; Philo, Rer. Div. Her. 66; Jos., C. Ap. 1, 66; 2, 141.—B-D-F § 302, 2; Rob. 751), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:3</a>; 3:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:10</a> (ver adiante).—Depois de <span class=\"greek\">οὐ</span>, reforçando-o (Appian, Liby. 90 §424 <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">δίδοτε</span> = vós nem sequer permitis): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἤθελεν</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὁφθαλμοὺς</span> <span class=\"greek\">ἐπᾶραι</span>, não queria nem levantar os olhos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:13</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:10</a> (ver acima).—GValley, Üb. d. Sprachgebr. des Longus, dissertação Ups. 1926, 36–44: acerca de <span class=\"greek\">οὔτε</span> e <span class=\"greek\">οὐδέ</span> em períodos posteriores.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐδείς, οὐδεμία, οὐδέν</h1><div class=\"entry-meta\"><span>adjetivo/pronome</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐδείς</span>, <span class=\"greek\">οὐδεμία</span>, <span class=\"greek\">οὐδέν</span> (Hom. e posteriores.—As formas <span class=\"greek\">οὐθείς</span> [Hs 9, 5, 6], <span class=\"greek\">οὐθέν</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:9</a>; 19:27; 26:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2</a>; Hm 4, 2, 1], <span class=\"greek\">οὐθενός</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:33</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:9</a>], para as quais frequentemente se lê <span class=\"greek\">οὐδ</span>- como variante nos manuscritos e edições, aparecem na literatura desde Aristóteles [Jos., Ant. 5, 250; 6, 47 e outros], nas inscrições [Meisterhans 3-Schw. 258f], e nos papiros [Mayser 181f], PStras II, 125, 4 [5/4 a.C.]; sobre essas formas, ver B-D-F § 33; W-S. §5, 27f e nota 62; Mlt-H. 111f; JWackernagel, Hellenistica 1907, 23; New Docs 2, 83; 4, 164f.—Sobre o emprego na LXX, Thackeray p. 58–62). ① Como adjetivo, nenhum: <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">προφήτης</span>, nenhum profeta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:24</a>. Cf. 16:13. <span class=\"greek\">παροιμία</span> <span class=\"greek\">οὐδεμία</span>, nenhuma parábola, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:29</a>. Cf. 18:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:18</a>; 27:22. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">εἴδωλον</span>, nenhum ídolo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:4a</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔχω</span>, não tenho necessidade de nada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:17</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:41</a>. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἄλλος</span> (UPZ 71, 15 [152 a.C.]), nenhum outro, 15:24.—<span class=\"greek\">οὐδεμία</span> <span class=\"greek\">ἐκκλησία</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὑμεῖς</span>, nenhuma igreja … senão vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:15</a>.—Com outras negativas: <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδεμίαν</span> <span class=\"greek\">δύναμιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:5</a>. ② Como substantivo. ⓐ <span class=\"greek\">οὐδείς</span>, ninguém, pessoa nenhuma, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>; 8:10; 9:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21f</a>; 5:4; 7:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36f</a>, 39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:18</a> (<span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">πώποτε</span>, como PGM 5, 102, sobre Osíris, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">εἶδε</span> <span class=\"greek\">πώποτε</span>; Jos., C. Ap. 2, 124); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:7b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:11</a>; 3:11 e frequentemente.—Com genitivo partitivo (Epict. 4, 1, 3 <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φαύλων</span>; Jos., Ant. 3, 321 <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἱερέων</span>; Just., D. 16, 3 <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὑμῶν</span>; Tat. 6:1 <span class=\"greek\">οὐδεμία</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span>): <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἀνθρώπων</span>, nenhum ser humano, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:2</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:24</a>. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνακειμένων</span>, nenhum dos convivas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:28</a>. <span class=\"greek\">τῶν</span> <span class=\"greek\">λοιπῶν</span> <span class=\"greek\">οὐδείς</span>, nenhum dos demais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:13</a>. <span class=\"greek\">οὐδ</span>. <span class=\"greek\">ὑμῶν</span>, nenhum de vós, 27:34 (Diod S 14, 65, 2 <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἡμῶν</span>). Cf. Ro. 14:7a. Em lugar do genitivo partitivo, pode ocorrer <span class=\"greek\">ἐκ</span> (Jos., Bell. 7, 398), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.61\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:61</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:19</a>; 16:5.—<span class=\"greek\">οὐδεὶς</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span>, ninguém … exceto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:27</a>; 17:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:22</a>; 18:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:14</a>; 8:4b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:17</a>; 14:3; 19:12. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἀπώλετο</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span>, nenhum deles pereceu, exceto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:12</a>.—Também <span class=\"greek\">οὐδεὶς</span> … <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:2</a>; 6:44, 65. Empregado com outras negativas (Appian, Samn. 11 §4 <span class=\"greek\">οὐδένα</span> <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">οὐδέν</span>, <span class=\"greek\">οὔτε</span> … <span class=\"greek\">οὔτε</span> = ninguém aceitou coisa alguma, nem … nem): <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδείς</span> (Appian, Bell. Civ. 1. 19 §80 = ninguém; Diog. L. 1, 53), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:27</a>; 5:37; 12:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:15</a>; 18:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:5</a>. <span class=\"greek\">οὓς</span> <span class=\"greek\">δέδωκάς</span> <span class=\"greek\">μοι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀπώλεσα</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">οὐδένα</span>, daqueles que me deste não perdi nenhum, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:9</a>. <span class=\"greek\">οὐκέτι</span> … <span class=\"greek\">οὐδείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:8</a>. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὔπω</span>, ninguém ainda, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a> (variante <span class=\"greek\">οὐδέπω</span>); <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὔπω</span> <span class=\"greek\">ἀνθρώπων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:2</a>. <span class=\"greek\">οὐδέπω</span> <span class=\"greek\">οὐδείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:16</a>. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὐκέτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:11</a>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἁλύσει</span> <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐδείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:3</a>.—<span class=\"greek\">οὐδενὶ</span> <span class=\"greek\">οὐδέν</span>, a ninguém nada, 16:8 (Appian, Liby. 128 §613 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">οὐδείς</span> = ninguém [ateou fogo a] coisa alguma [excluindo todas as exceções]; Just., D. 44, 2 <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οὐδέν</span> … <span class=\"greek\">οὐδαμόθεν</span> <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">ἔχει</span>. Sobre a bibliografia relativa ao silêncio das mulheres, ver FNeirynck, Evangelica ’82, 247–51). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:36</a>. <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐδείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:22</a>. ⓑ <span class=\"greek\">οὐδέν</span>, nada. <span class=\"greek\">α</span>. Literalmente: <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἀδυνατήσει</span> <span class=\"greek\">ὑμῖν</span>, nada vos será impossível, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:20</a>. Cf. 10:26; 26:62; 27:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:3</a>, variante de leitura. Seguido de genitivo partitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:36b</a>; 18:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:17</a>, variante de leitura (Mussies 183). Seguido de <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span>, nada senão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>; 21:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:29</a>; 11:13. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἐκτὸς</span> <span class=\"greek\">ὧν</span>, nada além do que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:22</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">διεφθάρη</span>, nenhuma parte de (Jonas) foi danificada, AcPlCor 2:30. Com outras negativas: <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδέν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:60f</a>; 15:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:27</a>, variante de leitura (por <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἕν</span>); 5:30; 9:33; 11:49. <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδενὶ</span> <span class=\"greek\">τούτων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:15a</a>. <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδέν</span>, <span class=\"greek\">ἄν</span> (= <span class=\"greek\">ἐὰν</span>) <span class=\"greek\">μή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:19</a>. <span class=\"greek\">οὐκέτι</span> … <span class=\"greek\">οὐδέν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:12</a>; 15:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:40</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀδικήσει</span>, nada vos causará dano, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:19</a> (ver <span class=\"greek\">ἀδικέω</span> 2). <span class=\"greek\">β</span>. Figuradamente, sem valor, sem significado, inválido (X., Cyr. 6, 2, 8; Diod S 14, 35, 5; Dio Chrys. 4, 60; 15 [32], 101 <span class=\"greek\">οὐδέν</span> <span class=\"greek\">ἐστι</span> = não significa nada, é insignificante; Tat. 27, 2 <span class=\"greek\">τῶν</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁμήγυρις</span> <span class=\"greek\">οὐδέν</span> <span class=\"greek\">ἐστιν</span>, «a reunião de muitos deuses não tem valor»): <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ὀμόσῃ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ναῷ</span>, <span class=\"greek\">οὐδέν</span> <span class=\"greek\">ἐστιν</span>, o juramento de quem jura pelo templo não obriga, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:16</a>, 18. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.54\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:54</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:19ab</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐδέν</span> <span class=\"greek\">εἰμι</span>, ainda que eu nada seja, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:11b</a>. <span class=\"greek\">οὐθέν</span> <span class=\"greek\">εἰμι</span>, nada sou, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2</a> ([Tat. 26, 3 <span class=\"greek\">οὐδέν</span> <span class=\"greek\">ἐστε</span>]; sobre o neutro referente a sujeito masculino, ver B-D-F § 131; Rob. 751).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a>; 25:11.—<span class=\"greek\">γενέσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐδέν</span>, reduzir-se a nada, 5:36. <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">συνέβη</span> <span class=\"greek\">τελευτῆσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τάξιν</span> <span class=\"greek\">αὐτῶν</span>, finalmente, o estatuto (dos anjos) foi anulado, Papias (4). <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐθὲν</span> <span class=\"greek\">λογισθῆναι</span>, ser considerado nada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:27</a>. Antônimo <span class=\"greek\">τίς</span> 2. <span class=\"greek\">γ</span>. O acusativo <span class=\"greek\">οὐδέν</span>, em aspecto nenhum, de modo nenhum (Dio Chrys. 52 [69], 6; Just., D. 14, 1 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">χρήσιμοι</span>; 68, 1 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">βλαβείην</span>.—B-D-F § 154; 160; Rob. 751): <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">διαφέρει</span>, (o herdeiro) em nada difere, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1</a>. <span class=\"greek\">οὐθὲν</span> <span class=\"greek\">διέκρινεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:9</a>. <span class=\"greek\">Ἰουδαίους</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἠδίκηκα</span>, não fiz mal algum aos judeus, 25:10; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:12</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὑστέρησα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:11a</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὠφελοῦμαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:3</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">σε</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ὠφελήσει</span>, pois isso em nada te aproveitará, AcPl Ha 2, 23. <span class=\"greek\">ἡ</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὠφελεῖ</span> <span class=\"greek\">οὐδέν</span>, a carne em nada aproveita, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:63</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">χρῄζει</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span>, (o Senhor) não precisa de coisa alguma, exceto, 1 Cl 52:1. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἥμαρτεν</span> <span class=\"greek\">Μάρκος</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἔνια</span> <span class=\"greek\">γράψας</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀπεμνημόνευσεν</span>, Marcos não errou ao registrar algumas coisas conforme se lembrava delas, Papias (2:15). Sobre <span class=\"greek\">οὐδέν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">διαφέρει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:6</a>, ver <span class=\"greek\">διαφέρω</span> 3.—Com o mesmo sentido, <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐδενί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>.—Às vezes se sugere o emprego posterior <span class=\"greek\">οὐδέν</span> = <span class=\"greek\">οὐ</span> (Aristoph., Eccl. 644; Dionys. Hal. [Rdm. 32, 5]; Epict. 4, 10, 36; POxy 1683, 13; BGU 948, 13), por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:17</a>.—M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐδέποτε</h1><div class=\"entry-meta\"><span>advérbio temporal negativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐδέποτε</span>, advérbio (Hom. e posteriores; Epict.; SIG 800, 29 <span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λειφθῇ</span>; PHib 78, 5 [244/243 a.C.]; POxy 1062, 11 [II d.C.]; LXX, pseudoepígrafos; Philo, Op. M. 12; Joseph., Just.), negação de ponto temporal indefinido, nunca, com presente (Just., D. 121, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:8</a> (sobre o assunto e o aspecto temporal, cf. Maximus Tyr. 14, 6e <span class=\"greek\">φιλία</span> <span class=\"greek\">χρόνῳ</span> <span class=\"greek\">αὔξεται</span>, «a amizade amadurece com o tempo»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:1</a>, 11. Com tempo passado (Diod S 14, 6, 1; Appian, Bell. Civ. 2, 139 §578; Jos., Bell. 5, 399, Ant. 13, 311), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:23</a>; 9:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:29ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:14</a>; 11:8; 14:8; IRo 3:1; Hm 3:3f; Hs 8, 10, 3; D 16:4. Com futuro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:33</a>; Hm 4, 1, 1.—Em perguntas: <span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">ἀνέγνωτε</span> … ;, nunca lestes …?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:16</a>, 42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:25</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐδέπω</h1><div class=\"entry-meta\"><span>advérbio temporal negativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐδέπω</span>, advérbio (Aeschyl., Pla. e posteriores; POxy 275, 8 [66 d.C.]; 273, 13; PRyl 178, 7; Ex 9:30; Jos., Bell. 2, 138, Ant, 14, 350), negação de prolongamento temporal até e além de um ponto esperado, ainda não, até agora não, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:8</a> P 66 (em lugar de <span class=\"greek\">οὐκ</span>), 39 (variante <span class=\"greek\">οὔπω</span>); 20:9; Hm 3:3. <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὐδέπω</span>, ninguém jamais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a>, variante de leitura (por <span class=\"greek\">οὔπω</span>). <span class=\"greek\">οὐδέπω</span> <span class=\"greek\">οὐδείς</span> (Jos., Ant. 6, 91), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:41</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:16</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐθείς</h1><div class=\"entry-meta\"><span>forma pronominal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐθείς</span>, ver <span class=\"greek\">οὐδείς</span>.—DELG s.v. <span class=\"greek\">οὐ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐκέτι</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐκέτι</span>, advérbio (<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔτι</span>, Tdf., Phlm 16; ambas as grafias no texto recebido; Hom. e posteriores). ① Extensão temporal até determinado ponto, mas não além dele, não mais, nunca mais, doravante não, literalmente sobre tempo (TestBenj 11:1; JosAs 15:6; Jos., Ant. 7, 16; Just., D. 56,23; Tat. 26, 3): <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">ἄξιος</span> <span class=\"greek\">κληθῆναι</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">σου</span>, já não sou digno de ser chamado teu filho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:19</a>, 21.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:42</a>; 6:66; 11:54; 15:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:9b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:19</a>; Phlm 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:6</a>; GJs 4:4.—Nunca mais (Jos., Ant. 6, 156; Artem. 3, 13 <span class=\"greek\">ἀθάνατοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀποθανόντες</span>, <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">μηκέτι</span> <span class=\"greek\">τεθνήξονται</span>): <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ἐγερθεὶς</span> … <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">ἀποθνῄσκει</span>, Cristo, ressuscitado …, já não morre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:9a</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:25</a>, 38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:23</a>.—Com presente, de evento no futuro iminente (cf. ApcEsdr 3:6 <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">ᾖ</span> <span class=\"greek\">κόσμος</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">με</span> <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">θεωρεῖ</span>, o mundo não mais me verá, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:19</a>; 16:10, 16; 17:11.—Com outra negativa: <span class=\"greek\">οὐ</span> … <span class=\"greek\">οὐκέτι</span> (Zeph 3:15; En 100:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:39</a>; <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐκέτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:46</a>. <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐδείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:3</a>. <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐδέν</span>, 7:12; 15:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:40</a>. <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐδείς</span> (UPZ 42, 30 [162 a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:8</a>. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὐκέτι</span>, 12:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:11</a>. <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span>, nunca mais (Am 9:15; TestJob 7:10 <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μη</span> <span class=\"greek\">φάγῃς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:16</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:14</a>. <span class=\"greek\">οὐκέτι</span> … <span class=\"greek\">οὐκέτι</span>, não mais … não mais, 8:2 (Polyaenus 1, 41, 2 <span class=\"greek\">οὐκέτι</span>, três vezes). ② Marcador de inferência em processo lógico, não (Melissus [V a.C.] B 9, Vorsokrat. 5 I 275 <span class=\"greek\">εἰ</span> … <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">εἴη</span>; cf. B 7, 2, ibidem p. 270; Empedocles B 17, 31, I 317 <span class=\"greek\">εἴτε</span> … <span class=\"greek\">οὐκέτ</span>’ <span class=\"greek\">ἂν</span> <span class=\"greek\">ἦσαν</span>; Ocellus c. 2 Harder; Ps.-Aristot., de Melisso etc. [ed. HDiels, ABA 1900] 1, 4; escólio sobre Apollon. Rhod. 2, 498–527a [p. 168, 23] <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυγάτηρ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἦν</span>, «portanto ela não era filha dele»; Ar. 13, 6 <span class=\"greek\">εἰ</span> …, <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">μία</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">ἐστίν</span>, «então certamente não compartilham uma característica comum»): então (por conseguinte) não, <span class=\"greek\">εἰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἔργων</span>, se é pela graça, então não pelas obras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:6a</a>. Cf. 7:20; 14:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:18</a>. Também <span class=\"greek\">νυνὶ</span> <span class=\"greek\">οὐκέτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:17</a>.—DELG s.v. <span class=\"greek\">ἔτι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐκοῦν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐκοῦν</span>, advérbio (<span class=\"greek\">οὐκ</span>, <span class=\"greek\">οὖν</span>; trágicos, Pla., X. e outros; 4 Km 5:23, variante de leitura). ① Inferencial, portanto, assim, consequentemente (Jos., C. Ap. 1, 171; 2, 226; Just., Tat., Ath.), B 5:3, 11, 12; 6:16; 7:1, 10; 9:4; 15:4; Dg 2:9; Hs 9, 28, 6. ② Interrogativo, quando a pergunta tem força inferencial, então, portanto (Menand., Epitr. 361 S. [185 Kö.]; 553 S. [377 Kö.]; Epict. 1, 7, 6; 8; 2, 24, 3 e outros; PHib 12, 4 [III a.C.]): <span class=\"greek\">οὐκοῦν</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">σύ</span>;, então tu és rei?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:37</a> (ver B-D-F § 451, 1; Rob. 1175; Kühner-G. II 163f; Schwyzer II 587–89).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Οὐλαμμαούς</h1><div class=\"entry-meta\"><span>nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Οὐλαμμαούς</span>, forma em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:13</a> D, no lugar de <span class=\"greek\">Ἐμμαοῦς</span>; influenciada pelo nome anterior de Betel, Gen 28:19 (ver edição de Rahlfs, 1926, 36).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖλος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὖλος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom. e outros), crespo, sobre cabelos (Plut., Cim. 481 [5, 3] <span class=\"greek\">οὔλῃ</span> <span class=\"greek\">τριχί</span>; Achilles Tat. 1, 4, 3; En 106:2; SibOr 13, 105), ApcPt 3:10.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0261-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐ μεν οὖν</h1><div class=\"entry-meta\"><span>locução adverbial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οὐ</span> <span class=\"greek\">μεν</span> <span class=\"greek\">οὖν</span> (assim Aristoph., Plu. 870, Ran. 556; 1188; também <span class=\"greek\">οὐμενοῦν</span>, Paus. 1, 21, 1), advérbio (Aristoph., Pla. e outros; inclusive Luc., Jupp. Tr. 35 duas vezes.—Kühner=G. II 158), marcador que introduz afirmação negativa em contradição ao discurso precedente, absolutamente não, de modo nenhum (expressando negação forte em resposta a uma pergunta), Dg 7:4.</p></section></article>"};
